const accountData = $('Métricas de la cuenta').item.json.data || [];
const postsData = $('Métricas de últimos posts').item.json.data || [];

const getMetric = (name) => {
  const m = accountData.find(d => d.name === name);
  return m?.values?.[1]?.value ?? 0;
};

const fecha = new Date();
fecha.setDate(fecha.getDate() - 1);
const fechaStr = fecha.toLocaleDateString('es-AR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const postsHtml = postsData.map(p => {
  const caption = (p.caption || '').slice(0, 60) + ((p.caption || '').length > 60 ? '...' : '');
  const imp = p.insights?.data?.find(d => d.name === 'impressions')?.values?.[0]?.value ?? '—';
  const reach = p.insights?.data?.find(d => d.name === 'reach')?.values?.[0]?.value ?? '—';
  const saved = p.insights?.data?.find(d => d.name === 'saved')?.values?.[0]?.value ?? '—';
  return `<tr>
    <td style='padding:6px 10px;font-size:13px'>${caption}</td>
    <td style='padding:6px 10px;text-align:center'>❤️ ${p.like_count || 0}</td>
    <td style='padding:6px 10px;text-align:center'>💬 ${p.comments_count || 0}</td>
    <td style='padding:6px 10px;text-align:center'>👁️ ${imp}</td>
    <td style='padding:6px 10px;text-align:center'>📍 ${reach}</td>
    <td style='padding:6px 10px;text-align:center'>🔖 ${saved}</td>
  </tr>`;
}).join('');

return [{
  json: {
    fechaStr,
    impresiones: getMetric('impressions').toLocaleString('es-AR'),
    alcance: getMetric('reach').toLocaleString('es-AR'),
    visitas_perfil: getMetric('profile_views').toLocaleString('es-AR'),
    clicks_web: getMetric('website_clicks').toLocaleString('es-AR'),
    seguidores: getMetric('follower_count').toLocaleString('es-AR'),
    postsHtml
  }
}];
